-- 要調整請改腳本或 object_catalog.json 後重跑。
--
-- 一、地圖：範圍 31..150（120x120 格），layout_mode=static（照生成點座標擺放）
-- 二、地形碰撞：外圈 6 格邊界帶整圈不可進入（2736 格），可走區為 37..144
-- 三、植被模板：footprint 與 blocking 與前端 catalog 逐項相同
-- 四、植被生成點：共 2464 個（邊界帶 1802 個塞滿；可走區 662 個，每 10x10 格 1~2 棵樹、3~5 個其他物件）
